create or replace TABLE SZD_PRODUCTION.CORE_REL.T_LOT_2 (
	PRODUCT_INSTANCE_GROUP_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the lot.',
	DWH_VALID_FROM_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record became valid.',
	DWH_VALID_TO_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was no longer valid.',
	DWH_VALID_FG BOOLEAN NOT NULL COMMENT 'An indicator showing the current record, i.e. where the current date is between dwh_valid_from and dwh_valid_to.',
	NOMINATED_FPOL_LOCATION_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the first port of loading VMT Software has recommended in the prenomination process',
	BOOKED_FPOL_LOCATION_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the actual booked first port of loading',
	NOMINATED_LPOD_LOCATION_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the last port of discharge VMT Software has recommended in the prenomination process',
	BOOKED_LPOD_LOCATION_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the last port of destination that will be used',
	DESTINATION_EXTERNAL_WAREHOUSE_RESOURCE_ITEM_SID NUMBER(38,0) NOT NULL COMMENT 'Unique identifier for the Destination / Target  Import Warehouse',
	ARRIVAL_VESSEL_RESOURCE_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the first oversea vessel',
	DEPARTURE_VESSEL_RESOURCE_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the name of the vessel that will arrive (for example after transshipments) at the destination port.',
	BOOKED_HAULER_PARTY_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the carrier acutally shipping the lot',
	NOMINATED_HAULER_PARTY_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the carrier VMT Software has recommended in the prenomination process',
	ORIGIN_HANDLING_AGENT_PARTY_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the original handling agent',
	DESTINATION_HANDLING_AGENT_PARTY_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the destination Handling Agent',
	DESTINATION_CUSTOMS_AGENT_PARTY_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the destination custom agent ',
	BOOKER_PARTY_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the party that performs the booking of the sea passage for a lot',
	VENDOR_PARTY_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the vendor',
	PRODUCER_PARTY_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the producer',
	SUPPLIER_PARTY_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the supplier_2',
	QCI_PARTY_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the qcc institute',
	PRODUCT_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the product.',
	LOT_NR VARCHAR(50) NOT NULL COMMENT 'Natural/Business key - The number which identifies the lot.',
	LOT_STATUS_CD VARCHAR(50) NOT NULL COMMENT 'The status_2 code for the lot',
	LOT_TRANSPORT_STATUS_CD VARCHAR(50) NOT NULL COMMENT 'Status_2 of lot transport name (e.g. could be also delayed)',
	EU_LOT_PROCESS_MODE_CD VARCHAR(50) NOT NULL COMMENT 'Processing mode defines who handles the unloading and the transport to the country_2 distribution center. ',
	BOOKED_FINAL_DESTINATION_CD VARCHAR(50) NOT NULL COMMENT 'Location_2 to where the shipment was booked to. Might be oversea port Rotterdam or inland terminal Moerdijk for example',
	INTERNATIONAL_TRANSPORT_ROUTE_TYPE_CD VARCHAR(50) NOT NULL COMMENT 'The unique code of the transport route type before import to a country.',
	INTERNATIONAL_TRANSPORT_TYPE_CD VARCHAR(50) NOT NULL COMMENT 'The unique identifier of the transport mode before import to a country.',
	DOMESTIC_TRANSPORT_ROUTE_TYPE_CD VARCHAR(50) NOT NULL COMMENT 'The unique code of the transport route type  after import to a country..',
	DOMESTIC_TRANSPORT_TYPE_CD VARCHAR(50) NOT NULL COMMENT 'The unique identifier of the transport mode after import to a country.',
	CONTAINER_PACKING_PLACE_CD VARCHAR(50) NOT NULL COMMENT 'Information where the container stuffing is taken place ',
	DANGEROUS_GOOD_TYPE_CD VARCHAR(50) NOT NULL COMMENT 'The classification of transported good as Dangerous Goods (SDB (Gefahrgut), Kein SDB )',
	PREDECESSOR_PRODUCT_IAN_NR VARCHAR(50) COMMENT 'Descriptive Attribute - Predecessor article of the current article',
	TARGET_DELIVERY_WEEK_START_DT DATE COMMENT 'Descriptive Attribute - Contractual  week where goods need to arrive in the country_2 distribution center',
	TARGET_OWIM_DELIVERY_WEEK_START_DT DATE COMMENT 'Descriptive Attribute - Calendar_2 week when the goods need to arrive at the OWIM warehouse',
	LAST_WAREHOUSE_ARRIVE_WEEK_START_DT DATE COMMENT 'Descriptive Attribute - LDD - Calendar_2 week when the goods need to arrive at the inbound warehouse at the latest',
	BOOKED_ETD_DT DATE COMMENT 'Descriptive Attribute - The ETD which was valid at the time the booking took place',
	BOOKED_ETA_DT DATE COMMENT 'Descriptive Attribute - The ETA which was valid at the time the booking took place',
	IN_LONGSTAY_TERMINAL_FG BOOLEAN COMMENT 'Inicator if the containers of a lot have been relocated to a longstay terminal',
	CLOSED_FG BOOLEAN NOT NULL COMMENT 'A lot can be closed if the goods are decided to be sent via plane instead for example or the shipment gets stolen, ship accident etc',
	CONSUMABLE_LOT_FG BOOLEAN NOT NULL COMMENT 'Indicates if lot contains consumables  - special articles with longer article numbers (9 digits)',
	DANGEROUS_GOOD_FG BOOLEAN NOT NULL COMMENT 'Information if a goods is shipped a dangerous goods',
	SENT_TO_INSPECTION_CENTER_FG BOOLEAN NOT NULL COMMENT 'Inspection center flag, if true, goods are sent to an inspection center',
	CONSOLIDATED_LOT_NR_TXT VARCHAR(1000) COMMENT 'Descriptive Attribute - lot numbers of lots that are consolidated with this one',
	ORDER_NR_TXT VARCHAR(1000) COMMENT 'Descriptive Attribute  - SAP Order number',
	INLAND_TERMINAL_NAME VARCHAR(100) COMMENT 'Descriptive Attribute - Name of the inland terminal ( inland intermodal terminal directly connected by road or rail to a seaport, operating as a centre for the transshipment of sea cargo to inland destinations)',
	CONSIGNEE_NAME VARCHAR(100) COMMENT 'Descriptive Attribute - Recipient of a shipment /owner of shipped goods',
	PRODUCT_BATCH_NR VARCHAR(50) NOT NULL COMMENT 'Relevant selection of the article',
	BILL_OF_LADING_NR_TXT VARCHAR(1000) COMMENT 'Descriptive Attribute - Official loading document title',
	BOOK_REFER_NR VARCHAR(50) COMMENT 'Descriptive Attribute - A name/primary key of a booking, stays equal over different systems ',
	CUSTOMS_CLEARANCE_CITY_NAME VARCHAR(100) COMMENT 'Descriptive Attribute - The city where customs check is done',
	CUSTOMS_CLEARANCE_COUNTRY_POL_CD VARCHAR(50) COMMENT 'The code identifying  for the country_2 of customs clearance',
	ORIGIN_COUNTRY_NAME VARCHAR(100) NOT NULL COMMENT 'Descriptive Attribute - The name of the country_2 of origin. Not the official countries name but an informal name',
	ORIGINAL_DEPARTING_VESSEL_RESOURCE_ITEM_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the original departing vessel',
	ORIGINAL_ARRIVING_VESSEL_RESOURCE_ITEM_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the original arriving vessel',
	ACTUAL_DEPARTING_VESSEL_RESOURCE_ITEM_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the actual departing vessel',
	ACTUAL_ARRIVING_VESSEL_RESOURCE_ITEM_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the actual arriving vessel',
	ORIGINALLY_CONFIRMED_ETD_TMSP TIMESTAMP_TZ(9) COMMENT 'The timestamp that was originally confirmed as the estimated time of departure (etd )',
	ORIGINALLY_CONFIRMED_ETA_TMSP TIMESTAMP_TZ(9) COMMENT 'The timestamp that was originally confirmed as the estimated time of arrival (eta )',
	SHIPPED_ATD_TMSP TIMESTAMP_TZ(9) COMMENT 'The timestamp the shipment was actually shipped on ( atd )',
	SHIPPED_ETA_TMSP TIMESTAMP_TZ(9) COMMENT 'The timestamp the shipment is estimated to arrive ( eta )',
	DWH_CREATED_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was created in the data warehouse.',
	DWH_UPDATED_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was created or last updated.',
	DWH_SRC_FILE_NAME VARCHAR(500) NOT NULL COMMENT 'The path and the name of the file(s) from which this record was loaded.',
	DWH_SRC_1_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was extracted from the source.',
	constraint PK_LOT primary key (PRODUCT_INSTANCE_GROUP_SID, DWH_VALID_FROM_TMSP)
)COMMENT='Major Entity - A lot is defined as the amount of shipped cartons per IAN+batch in the same shipment. There can be several lots on the same vessel . shipment in VMT is a lot (containers shipped in the same booking process) - Source - VMT'
;